/**
 * Which atlas a scratch page loads — H3's acceptance check, in one place.
 *
 * H1 gave the repository two spritesheets with the same frame names at two densities, and
 * from H3 on the scratch pages are how the HD one is reviewed. The switch is a URL
 * parameter rather than a build flag so a before/after pair is two browser tabs:
 *
 *   /tiles.html          the HD sheet, linear
 *   /tiles.html?hd=0     the SD sheet, nearest — the pre-HD look, unchanged
 *
 * `atlas.html` reads both at once and toggles between them live, which is the only way to
 * judge a silhouette: the eye is far better at spotting a change than a difference.
 *
 * This is deliberately *not* `core/Platform`'s flag. H0 owes the game one of those, H6
 * makes it select filtering and `roundPixels` as well, and H10 turns it into one coherent
 * retro mode. Until then the scratch pages have their own, and nothing in `src/core` or
 * `src/game` knows either exists.
 */
import { Assets, type Spritesheet } from 'pixi.js';

/** The two sheets, by density. `assets/` is the static root, so both paths are relative. */
export const SD_ATLAS = 'atlas.json';
export const HD_ATLAS = 'hd/atlas.json';

/**
 * `?hd=0` off, `?hd=1` on, absent takes `fallback`.
 *
 * The pages that exist to look at art default to HD; `perf.html` defaults to SD, because
 * its numbers are T13's baseline and H6 is the task that re-measures them.
 */
export function hdEnabled(fallback = true): boolean {
  const value = new URLSearchParams(window.location.search).get('hd');
  if (value === null) return fallback;
  return value !== '0';
}

/**
 * Load one sheet and set its filtering to match its density.
 *
 * `nearest` on the SD sheet is the original decision and the reason the pixel art is
 * crisp; `linear` on the HD sheet is the one that lets 8 texels behind a virtual pixel
 * actually show. H6 makes the same choice for the game itself.
 */
export async function loadSheet(hd: boolean): Promise<Spritesheet> {
  const sheet: Spritesheet = await Assets.load(hd ? HD_ATLAS : SD_ATLAS);
  sheet.textureSource.scaleMode = hd ? 'linear' : 'nearest';
  return sheet;
}

/** A one-line banner for a page that has picked a sheet, so a screenshot says which. */
export function sheetLabel(hd: boolean): string {
  return hd ? 'HD 8x (?hd=0 for SD)' : 'SD 1x (?hd=1 for HD)';
}
